package com.ruoyi.web.controller.projectmanagement;
import com.ruoyi.common.core.controller.BaseController;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.projectmanagement.wbs.domain.ProjectWbsNode;import com.ruoyi.projectmanagement.wbs.service.IProjectWbsService;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/projectManagement/wbs")
public class ProjectWbsController extends BaseController {private final IProjectWbsService service;public ProjectWbsController(IProjectWbsService service){this.service=service;}@GetMapping("/tree")public AjaxResult tree(ProjectWbsNode f){return success(service.list(f));}@GetMapping("/{id}")public AjaxResult get(@PathVariable Long id){return success(service.get(id));}@PostMapping public AjaxResult add(@Validated @RequestBody ProjectWbsNode n){n.setCreateBy(getUsername());int rows=service.add(n,getUsername());AjaxResult r=toAjax(rows);if(rows>0)r.put("data",n.getWbsId());return r;}@PutMapping public AjaxResult edit(@Validated @RequestBody ProjectWbsNode n){n.setUpdateBy(getUsername());return toAjax(service.edit(n,getUsername()));}@DeleteMapping("/{id}")public AjaxResult remove(@PathVariable Long id){return toAjax(service.remove(id,getUsername()));}}
